mapper.select:
SELECT EXISTS (
    SELECT 1 FROM sys_user
    WHERE english_nickname = #{englishNickname}
      AND deleted_at = 0
    
      AND id != #{excludeId}
    
)

mapper.update:
UPDATE sys_user
SET status = 0, deleted_at = #{deletedAt}, updated_by = #{updatedBy}
WHERE id = #{id} AND deleted_at = 0
